<?php require 'config.php'; fechar_offlines(); $id=$_GET['id']??''; $f=null; foreach(jread('funcionarios',[]) as $ff){ if(($ff['id']??'')===$id) $f=$ff; } if(!$f){ header_page('Funcionário'); echo '<div class="card"><h2>Funcionário não encontrado.</h2></div>'; footer_page(); exit; } header_page('Ficha do funcionário');
$ym=$_GET['mes']??date('Y-m'); $pres=jread('presencas',[]); $dev=dispositivo_do_funcionario($id); $mes=resumo_funcionario_mes($id,$ym); $media=media_entrada_func($id); ?>
<section class="hero"><div><h2><?=h($f['nome'])?></h2><p><?=h($f['cargo']??'Funcionário')?> · <?=h($f['telefone']??'')?></p></div><form><input type="hidden" name="id" value="<?=h($id)?>"><input type="month" name="mes" value="<?=h($ym)?>"><button class="btn">Filtrar</button></form></section>
<section class="grid kpis"><div class="card"><p>Horas no mês</p><div class="big"><?=hhmm_from_min($mes['minutos'])?></div></div><div class="card"><p>Extras no mês</p><div class="big"><?=hhmm_from_min($mes['extra'])?></div></div><div class="card"><p>Atrasos</p><div class="big warn"><?=$mes['atrasos']?></div></div><div class="card"><p>Média entrada</p><div class="big smallbig"><?=$media!==null?hhmm_from_min($media):'--'?></div></div></section><br>
<div class="card"><h2>Celular cadastrado</h2><?php if($dev): ?><p><b>IP:</b> <?=h($dev['ip']??'')?> · <b>MAC:</b> <?=h($dev['mac']??'')?> · <b>Último visto:</b> <?=h($dev['ultimo_visto']??'')?></p><p class="muted"><?=h($dev['user_agent']??'')?></p><?php else: ?><p>Nenhum celular vinculado.</p><?php endif; ?></div><br>
<div class="card"><h2>Histórico do mês</h2><table><tr><th>Data</th><th>Entrada</th><th>Saída</th><th>Almoço</th><th>Total</th><th>Extra</th><th>Status</th></tr><?php foreach($pres as $p): if(($p['funcionario_id']??'')!==$id || substr($p['data']??'',0,7)!==$ym) continue; ?><tr><td><?=date('d/m/Y',strtotime($p['data']))?></td><td><?=!empty($p['entrada'])?date('H:i',strtotime($p['entrada'])):'--'?></td><td><?=!empty($p['saida'])?date('H:i',strtotime($p['saida'])):'--'?></td><td><?=hhmm_from_min($p['almoco_minutos']??0)?></td><td><?=hhmm_from_min($p['minutos']??0)?></td><td><?=hhmm_from_min($p['extra_minutos']??0)?></td><td><?=h($p['status']??'')?></td></tr><?php endforeach; ?></table></div>
<?php footer_page(); ?>
